export { BlToast } from './toast.js';
export { BlToastRegion, toast } from './toast-region.js';
export type { ToastVariant } from './toast.js';
export type { ToastPosition, ToastOptions } from './toast-region.js';

import { css } from 'lit';

export const toastRegionStyles = css`
  :host {
    display: block;
    position: fixed;
    z-index: var(--bl-z-toast);
    pointer-events: none;
    padding: var(--bl-spacing-md);
  }

  /* Position variants */
  :host([position='top-left']) {
    top: 0;
    left: 0;
  }
  :host([position='top-center']) {
    top: 0;
    left: 50%;
    transform: translateX(-50%);
  }
  :host([position='top-right']),
  :host(:not([position])) {
    top: 0;
    right: 0;
  }
  :host([position='bottom-left']) {
    bottom: 0;
    left: 0;
  }
  :host([position='bottom-center']) {
    bottom: 0;
    left: 50%;
    transform: translateX(-50%);
  }
  :host([position='bottom-right']) {
    bottom: 0;
    right: 0;
  }

  .toast-list {
    display: flex;
    flex-direction: column;
    gap: var(--bl-spacing-sm);
  }

  /* Stack from bottom for top positions */
  :host([position='bottom-left']) .toast-list,
  :host([position='bottom-center']) .toast-list,
  :host([position='bottom-right']) .toast-list {
    flex-direction: column-reverse;
  }
`;

import { LitElement, html } from 'lit';
import { customElement, property } from 'lit/decorators.js';
import { tokens } from '../../styles/tokens.js';
import { toastRegionStyles } from './toast-region.styles.js';
import { announce } from '../../primitives/live-announce/live-announce.js';
import type { BlToast, ToastVariant } from './toast.js';

export type ToastPosition =
  | 'top-left'
  | 'top-center'
  | 'top-right'
  | 'bottom-left'
  | 'bottom-center'
  | 'bottom-right';

export interface ToastOptions {
  /** Visual variant. */
  variant?: ToastVariant;
  /** Auto-dismiss duration in ms. */
  duration?: number;
  /** Action button label. */
  action?: {
    label: string;
    onClick: () => void;
  };
}

// Global toast manager singleton
let _defaultRegion: BlToastRegion | null = null;

/**
 * Imperative toast API. Shows a toast in the default (or first) toast region.
 *
 * @example
 * ```js
 * import { toast } from '@blink-ui/components/toast';
 * toast('File saved successfully', { variant: 'success' });
 * ```
 */
export function toast(message: string, options?: ToastOptions): void {
  if (!_defaultRegion) {
    // Auto-create a default region if none exists
    _defaultRegion = document.createElement('bl-toast-region') as BlToastRegion;
    document.body.appendChild(_defaultRegion);
  }
  _defaultRegion.addToast(message, options);
}

/**
 * A container region for toast notifications.
 *
 * @element bl-toast-region
 * @slot - Toasts are appended here dynamically.
 */
@customElement('bl-toast-region')
export class BlToastRegion extends LitElement {
  static override styles = [tokens, toastRegionStyles];

  /** Position of the toast region. */
  @property({ reflect: true })
  position: ToastPosition = 'top-right';

  /** Maximum number of visible toasts. */
  @property({ type: Number })
  max = 5;

  private _toasts: BlToast[] = [];

  override connectedCallback(): void {
    super.connectedCallback();
    this.setAttribute('role', 'region');
    this.setAttribute('aria-live', 'polite');
    this.setAttribute('aria-label', 'Notifications');

    // Register as default region
    if (!_defaultRegion) {
      _defaultRegion = this;
    }
  }

  override disconnectedCallback(): void {
    super.disconnectedCallback();
    if (_defaultRegion === this) {
      _defaultRegion = null;
    }
  }

  /** Programmatically add a toast. */
  async addToast(message: string, options?: ToastOptions): Promise<void> {
    // Respect max visible count
    while (this._toasts.length >= this.max) {
      const oldest = this._toasts.shift();
      oldest?.dismiss();
    }

    // Import dynamically to avoid circular reference at module level
    const toastEl = document.createElement('bl-toast') as BlToast;
    toastEl.message = message;
    if (options?.variant) toastEl.variant = options.variant;
    if (options?.duration !== undefined) toastEl.duration = options.duration;

    toastEl.addEventListener('bl-toast-dismiss', () => {
      const idx = this._toasts.indexOf(toastEl);
      if (idx !== -1) this._toasts.splice(idx, 1);
    });

    if (options?.action) {
      const btn = document.createElement('button');
      btn.textContent = options.action.label;
      btn.slot = 'action';
      btn.style.cssText =
        'background:none;border:none;color:var(--bl-color-primary-600);cursor:pointer;font-size:var(--bl-font-size-sm);font-weight:500;padding:0;';
      btn.addEventListener('click', () => {
        options.action!.onClick();
        toastEl.dismiss();
      });
      toastEl.appendChild(btn);
    }

    this._toasts.push(toastEl);

    const list = this.shadowRoot!.querySelector('.toast-list');
    list?.appendChild(toastEl);

    // Announce for screen readers
    announce(message, 'polite');

    // Trigger enter animation
    await toastEl.show();
  }

  protected override render() {
    return html`<div class="toast-list"></div>`;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'bl-toast-region': BlToastRegion;
  }
}

import { css } from 'lit';

export const toastStyles = css`
  :host {
    display: block;
    pointer-events: auto;
  }

  .toast {
    display: flex;
    align-items: flex-start;
    gap: var(--bl-spacing-sm);
    padding: var(--bl-spacing-sm) var(--bl-spacing-md);
    background-color: #fff;
    border: 1px solid var(--bl-color-neutral-200);
    border-radius: var(--bl-radius-md);
    box-shadow: var(--bl-shadow-lg);
    font-family: var(--bl-font-family-base);
    font-size: var(--bl-font-size-sm);
    color: var(--bl-color-neutral-800);
    min-width: 280px;
    max-width: 420px;

    opacity: 0;
    transform: translateY(8px);
    transition:
      opacity var(--bl-animation-duration-normal) var(--bl-animation-easing-enter),
      transform var(--bl-animation-duration-normal) var(--bl-animation-easing-enter);
  }

  .toast[data-state='entering'],
  .toast[data-state='entered'] {
    opacity: 1;
    transform: translateY(0);
  }

  .toast[data-state='exiting'] {
    opacity: 0;
    transform: translateY(8px);
    transition:
      opacity var(--bl-animation-duration-fast) var(--bl-animation-easing-exit),
      transform var(--bl-animation-duration-fast) var(--bl-animation-easing-exit);
  }

  /* Variants */
  :host([variant='success']) .toast {
    border-left: 3px solid var(--bl-color-success-500);
  }

  :host([variant='warning']) .toast {
    border-left: 3px solid var(--bl-color-warning-500);
  }

  :host([variant='danger']) .toast {
    border-left: 3px solid var(--bl-color-danger-500);
  }

  .toast-content {
    flex: 1;
    line-height: 1.5;
  }

  .toast-close {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 24px;
    height: 24px;
    padding: 0;
    flex-shrink: 0;
    background: none;
    border: none;
    border-radius: var(--bl-radius-sm);
    color: var(--bl-color-neutral-400);
    cursor: pointer;
    transition:
      background-color var(--bl-transition-fast),
      color var(--bl-transition-fast);
  }

  .toast-close:hover {
    background-color: var(--bl-color-neutral-100);
    color: var(--bl-color-neutral-600);
  }

  .toast-action {
    flex-shrink: 0;
  }
`;

import { LitElement, html, nothing } from 'lit';
import { customElement, property } from 'lit/decorators.js';
import { tokens } from '../../styles/tokens.js';
import { toastStyles } from './toast.styles.js';
import { AnimationController } from '../controllers/animation.js';

export type ToastVariant = 'default' | 'success' | 'warning' | 'danger';

/**
 * A single toast notification. Normally created by the `toast()` API.
 *
 * @element bl-toast
 * @slot - Toast message content.
 * @slot action - Action button content.
 * @csspart toast - The toast container.
 * @fires bl-toast-dismiss - Emitted when the toast is dismissed.
 */
@customElement('bl-toast')
export class BlToast extends LitElement {
  static override styles = [tokens, toastStyles];

  private _animation = new AnimationController(this, { enterDuration: 200, exitDuration: 150 });
  private _timer: ReturnType<typeof setTimeout> | null = null;

  /** Visual variant. */
  @property({ reflect: true })
  variant: ToastVariant = 'default';

  /** Auto-dismiss duration in ms. 0 disables auto-dismiss. */
  @property({ type: Number })
  duration = 5000;

  /** The toast message. Can also be set via default slot. */
  @property()
  message = '';

  override connectedCallback(): void {
    super.connectedCallback();
    this.addEventListener('mouseenter', this._pauseTimer);
    this.addEventListener('mouseleave', this._resumeTimer);
  }

  override disconnectedCallback(): void {
    super.disconnectedCallback();
    this._clearTimer();
    this.removeEventListener('mouseenter', this._pauseTimer);
    this.removeEventListener('mouseleave', this._resumeTimer);
  }

  /** Animate the toast in and start the auto-dismiss timer. */
  async show(): Promise<void> {
    await this.updateComplete;
    const surface = this.shadowRoot!.querySelector<HTMLElement>('.toast');
    if (surface) {
      await this._animation.enter(surface);
    }
    this._startTimer();
  }

  /** Animate the toast out and remove it. */
  async dismiss(): Promise<void> {
    this._clearTimer();
    const surface = this.shadowRoot!.querySelector<HTMLElement>('.toast');
    if (surface) {
      await this._animation.exit(surface);
    }
    this.dispatchEvent(
      new CustomEvent('bl-toast-dismiss', { composed: true, bubbles: true }),
    );
    this.remove();
  }

  private _startTimer(): void {
    if (this.duration > 0) {
      this._timer = setTimeout(() => this.dismiss(), this.duration);
    }
  }

  private _clearTimer(): void {
    if (this._timer) {
      clearTimeout(this._timer);
      this._timer = null;
    }
  }

  private _pauseTimer = (): void => {
    this._clearTimer();
  };

  private _resumeTimer = (): void => {
    this._startTimer();
  };

  private _handleClose = (): void => {
    this.dismiss();
  };

  protected override render() {
    return html`
      <div class="toast" part="toast" role="status">
        <div class="toast-content">
          ${this.message || html`<slot></slot>`}
        </div>
        <div class="toast-action">
          <slot name="action"></slot>
        </div>
        <button
          class="toast-close"
          part="close"
          aria-label="Dismiss"
          @click=${this._handleClose}
        >
          <svg
            width="14"
            height="14"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width="2"
            stroke-linecap="round"
            stroke-linejoin="round"
            aria-hidden="true"
          >
            <line x1="18" y1="6" x2="6" y2="18"></line>
            <line x1="6" y1="6" x2="18" y2="18"></line>
          </svg>
        </button>
      </div>
    `;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'bl-toast': BlToast;
  }
}
